import type {
  Persona,
  SegmentFAQ,
  SegmentFundingNotes,
  SegmentMidCta,
  SegmentMeta,
  SegmentExperienceFilterHints,
  SegmentSchoolFilterHints,
} from '@/lib/segments/types';

// ============================================================
// 都市マスターデータ
// 各国の主要都市を slug + 日本語名 + 英語名 + 概要 で定義
// /countries/[slug]/cities/[city] のジェネレータが参照
// ============================================================

// 各都市の詳細説明（留学検討者向け）
// AI生成スクリプトで雛形を作り、編集者が手で校正する
// 各セクション 200-300字程度を想定
export type CityFitItem = {
  type: string;     // 例: '英語環境にどっぷり浸かりたい人'
  reason: string;   // 理由を1〜2文で
};

export type CityFirstStep = {
  when: string;     // 例: '初日' '1〜3日目' '1週間以内' '1ヶ月以内'
  title: string;    // 例: 'SIMと交通カードを購入'
  body: string;     // 具体的な行動（2〜3文）
};

export type CityDetails = {
  areaOverview?: string;   // このエリアはどんな街か
  climate?: string;        // 気候・季節の特徴
  safety?: string;         // 治安と注意点
  cityscape?: string;      // 街並みとエリア区分
  transport?: string;      // 交通アクセス・移動
  living?: string;         // 生活環境・暮らしの特徴
  forStudents?: string;    // 留学・ワーホリ参加者向けの魅力
  costSummary?: string;    // 生活費の目安（要約、詳細は liveCostArticleSlug の記事へ）
  // 差別化セクション（観光ガイドとは異なる「留学者目線」の独自情報）
  goodFit?: CityFitItem[];      // この街が向いている人（3〜5項目）
  notFit?: CityFitItem[];       // 注意したい人・向かない場合（2〜3項目）
  firstSteps?: CityFirstStep[]; // 到着〜1週間〜1ヶ月でやること
  realVoice?: string;           // 編集部目線のリアル（観光ガイドが書かない本音）
};

export type CityMaster = {
  slug: string;
  countrySlug: string;
  nameJp: string;
  nameEn: string;
  description: string;
  population?: number;
  monthlyLivingJpy?: number;
  highlights?: string[];

  // エリア説明（新規）
  cityDetails?: CityDetails;
  liveCostArticleSlug?: string;

  // SegmentMeta 拡張（optional）
  h1Override?: string;
  metaTitle?: string;
  metaDescription?: string;
  heroLead?: string;
  keyTakeaways?: string[];
  personas?: Persona[];
  scenarioKeys?: string[];
  faqOverrides?: SegmentFAQ[];
  midCta?: SegmentMidCta;
  relatedArticleSlugs?: string[];
  fundingNotes?: SegmentFundingNotes;
  showFundingCard?: boolean;
  showROICard?: boolean;
  showCostEstimator?: boolean;
  schoolFilterHints?: SegmentSchoolFilterHints;
  experienceFilterHints?: SegmentExperienceFilterHints;
  monthsAssumedForSchoolEstimate?: number;
};

